// TH16 v1.00a st05.ecl.txt: ECir00 / ECir00_at（dependency，行 4-41、105-154）。
// 三组环形编队的每个成员：出生抖动回零 -> 60 帧后可体碰 -> 每 60 帧一组自机狙单发。
// 死亡回调 ECir00DeadAttack1/Et1（行 43-103）在无敌外壳内不可达，见 report.md。

// etSprite(0, 4, 6) -> 原作 type4/color6；复用的已核 TH16 别名。
const TH16_BALL: int = 416;

// enmCreate("ECir00", ...) 的 150/1000/1：hp=150、score=1000；掉落按训练口径省略。
const ECIR_HP: int = 150;
const ECIR_SCORE: int = 1000;

// 行 995/998/...: circlePos(%A, %B, angle, 64.0f) 后 enmCreate 到 (%C+%A, %D+%B)。
// 父为关卡上下文 (0,0)，相对创建即这些世界坐标。
sub spawn_on_ring(cx: fx, cy: fx, a: angle) {
    spawn_ecir_at(cx + 64fx * cos(a), cy + 64fx * sin(a));
}
sub spawn_center(cx: fx, cy: fx) {
    spawn_ecir_at(cx, cy);
}

// 行 22: movePosRel(%RANDF2 * 16, %RANDF2 * 16)。先抽 x 再抽 y，两次独立读取。
sub spawn_ecir_at(px: fx, py: fx) {
    var jx: fx = ((rand(65536) - 32768) as fx / 32768) * 16fx;
    var jy: fx = ((rand(65536) - 32768) as fx / 32768) * 16fx;
    _ = spawn_enemy(px + jx, py + jy, ECIR_HP, 0, ECIR_SCORE, 0, ecir_body(px, py));
}

async sub ecir_body(px: fx, py: fx) {
    set_invuln(65535);
    // 行 10-11: setHurtbox(24,24) / setHitbox(16,16)，普通圆形取第一值×0.5。
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 行 15 flagSet(15)：其中 0x2 为禁体碰；0x4/0x8 屏外回收豁免在本段不可达。
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // 行 23: movePosRelTime(60, 1, 0, 0)，mode1=t²；从抖动位置回到 (px,py)。
    move_to(60, px, py, EASE_QUAD_IN);
    wait(60);
    // 行 27 flagClear(15)
    set_enemy_flag(ENEMY_NO_BODY, 0);
    // 行 30: @ECir00_at() async
    spawn ecir_at();
    wait(60);
    // 行 32-34: getAngle(...,FINAL,(0,191)) -> moveVel(angle, 0) -> moveSpeedTime(120, 0, 1.0)
    move_angle(0, atan2(191fx - $self_y, 0fx - $self_x), EASE_LINEAR);
    move_speed(120, 1fx, EASE_LINEAR);
    // 行 36-39: 无限等待，敌保持存活。
    loop { wait(1000); }
}

async sub ecir_at() {
    wait(10);
    // 行 116-121 / 127 / 141-149：速度、散布、发数、间隔的难度分支。
    var rank: int = global(GVAR_RANK);
    var spd: fx = 1fx;
    var spread: angle = 1deg;
    var interval: int = 120;
    var shots: int = 1;
    if rank == RANK_NORMAL { spd = 2fx; spread = 10deg; shots = 2; }
    if rank == RANK_HARD { spd = 2.5fx; spread = 20deg; interval = 30; shots = 4; }
    if rank == RANK_LUNATIC { spd = 3fx; spread = 30deg; interval = 10; shots = 20; }
    for i in 0..shots {
        // 行 129-139: ANGLE_PLAYER + RANDF2*spread，每发抽一次。
        var u: fx = (rand(65536) - 32768) as fx / 32768;
        var off: int = (u * (spread as int)) as int;
        var a: angle = aim_player() + (off as angle);
        // 行 124 EX type2 ANIM a=1：出生位移 position -= 4*velocity。
        var bx: fx = $self_x - 4fx * spd * cos(a);
        var by: fx = $self_y - 4fx * spd * sin(a);
        _ = fire(TH16_BALL, 6, bx, by, spd, a, none, none);
        wait(interval);
    }
}

// TH16 v1.00a Stage 5 道中 wave：st05.ecl.txt::MainSub00:990-1051。
// 三组环形编队（中心 (0,128)/(64,128)/(-64,128)），每组 5 只绕半径 64 的 ECir00 + 1 只中心。
// 外壳：validation.md 独立无敌段；源时间从 pattern 的 OPENING_BUFFER 之后起算。

const TIME_LIMIT: int = 774;
const OPENING_BUFFER: int = 120;

// 时间轴（源帧，MainSub00 进入为 0）：
// 环 1: 0,10,20,30,40,50(中心) + wait80 -> 130
// 环 2: 130..180 + wait80 -> 260
// 环 3: 260..310 + wait100 -> 410 返回
// 尾弹：环 3 中心敌 310+60+10+19*10 = 570（Lunatic 最晚一发）。
// 源段估计 650（准备/排程/尾弹），卡时限 120+650+4=774。
async sub pattern() {
    wait(OPENING_BUFFER);

    // 行 993-1011: %C=0, %D=128；角度 -1.5707964, 0.9424778, 3.455752, -0.31415927, 2.1991148。
    spawn_on_ring(0fx, 128fx, -90deg); wait(10);
    spawn_on_ring(0fx, 128fx, 54deg); wait(10);
    spawn_on_ring(0fx, 128fx, 198deg); wait(10);
    spawn_on_ring(0fx, 128fx, -18deg); wait(10);
    spawn_on_ring(0fx, 128fx, 126deg); wait(10);
    spawn_center(0fx, 128fx);
    wait(80);

    // 行 1012-1029: %C=64；角度 -1.5707964, -4.0840707, -6.5973444, -2.8274333, -5.3407073。
    spawn_on_ring(64fx, 128fx, -90deg); wait(10);
    spawn_on_ring(64fx, 128fx, -234deg); wait(10);
    spawn_on_ring(64fx, 128fx, -378deg); wait(10);
    spawn_on_ring(64fx, 128fx, -162deg); wait(10);
    spawn_on_ring(64fx, 128fx, -306deg); wait(10);
    spawn_center(64fx, 128fx);
    wait(80);

    // 行 1031-1049: %C=-64；角度与环 1 相同。
    spawn_on_ring(-64fx, 128fx, -90deg); wait(10);
    spawn_on_ring(-64fx, 128fx, 54deg); wait(10);
    spawn_on_ring(-64fx, 128fx, 198deg); wait(10);
    spawn_on_ring(-64fx, 128fx, -18deg); wait(10);
    spawn_on_ring(-64fx, 128fx, 126deg); wait(10);
    spawn_center(-64fx, 128fx);
    wait(100);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
